import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { toast } from "sonner";
import { authApi } from "../../../lib/api";
import { useAuth } from "../../../context/AuthContext";
import { Button } from "../../../components/ui/button";
import { Input } from "../../../components/ui/input";
import { Label } from "../../../components/ui/label";
import { Textarea } from "../../../components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "../../../components/ui/select";
import { Checkbox } from "../../../components/ui/checkbox";
import { DEFAULT_PROGRAM_FIELDS } from "../../../components/programs/DynamicFormFields";
import { Plus, Trash2, ExternalLink } from "lucide-react";

function slugify(text) {
  return String(text || "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

export default function ProgramsPage() {
  const { can } = useAuth();
  const canEdit = can("programs", "edit");
  const canDelete = can("programs", "delete");
  const [types, setTypes] = useState([]);
  const [programs, setPrograms] = useState([]);
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({
    title: "", slug: "", type_id: "", description: "", venue: "",
    admin_email: "", starts_at: "", ends_at: "",
    registration_opens_at: "", registration_closes_at: "",
    is_active: true, allow_public_registration: true,
    form_fields: DEFAULT_PROGRAM_FIELDS,
  });
  const [editing, setEditing] = useState(null);
  const [fieldDraft, setFieldDraft] = useState({ name: "", label: "", type: "text", required: false });

  const load = async () => {
    const [t, p] = await Promise.all([authApi.listProgramTypes(), authApi.listPrograms()]);
    setTypes(t);
    setPrograms(p);
  };
  useEffect(() => { load().catch((e) => toast.error(e.message)); }, []);

  const reset = () => {
    setForm({
      title: "", slug: "", type_id: "", description: "", venue: "",
      admin_email: "", starts_at: "", ends_at: "",
      registration_opens_at: "", registration_closes_at: "",
      is_active: true, allow_public_registration: true,
      form_fields: [...DEFAULT_PROGRAM_FIELDS],
    });
    setEditing(null);
    setOpen(false);
  };

  const save = async (e) => {
    e.preventDefault();
    await authApi.upsertProgram(editing?.id || null, {
      ...form,
      slug: form.slug || slugify(form.title),
      form_fields: form.form_fields,
    });
    toast.success(editing ? "Program updated" : "Program created");
    reset();
    load();
  };

  const addField = () => {
    if (!fieldDraft.name || !fieldDraft.label) return;
    setForm({
      ...form,
      form_fields: [...form.form_fields, { ...fieldDraft, name: slugify(fieldDraft.name).replace(/-/g, "_") }],
    });
    setFieldDraft({ name: "", label: "", type: "text", required: false });
  };

  const editProgram = (p) => {
    setEditing(p);
    setForm({
      title: p.title, slug: p.slug, type_id: p.type_id || "", description: p.description || "",
      venue: p.venue || "", admin_email: p.admin_email || "",
      starts_at: p.starts_at ? p.starts_at.slice(0, 16) : "",
      ends_at: p.ends_at ? p.ends_at.slice(0, 16) : "",
      registration_opens_at: p.registration_opens_at ? p.registration_opens_at.slice(0, 16) : "",
      registration_closes_at: p.registration_closes_at ? p.registration_closes_at.slice(0, 16) : "",
      is_active: p.is_active, allow_public_registration: p.allow_public_registration,
      form_fields: p.form_fields?.length ? p.form_fields : [...DEFAULT_PROGRAM_FIELDS],
    });
    setOpen(true);
  };

  return (
    <div>
      <div className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <p className="text-xs uppercase tracking-[0.25em] text-red-600 font-semibold">Programs</p>
          <h1 className="text-3xl font-bold mt-2">Church programs</h1>
          <p className="text-gray-500 mt-2 text-sm">Create programs with custom registration fields and public links.</p>
        </div>
        {canEdit && (
          <Button className="bg-red-600 hover:bg-red-700" onClick={() => { reset(); setOpen(true); }}>
            <Plus size={16} className="mr-2" /> New program
          </Button>
        )}
      </div>

      {open && canEdit && (
        <form onSubmit={save} className="mt-6 rounded-2xl border bg-white p-6 space-y-5">
          <div className="grid md:grid-cols-2 gap-4">
            <div className="space-y-2"><Label>Title</Label><Input value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value, slug: form.slug || slugify(e.target.value) })} required /></div>
            <div className="space-y-2"><Label>URL slug</Label><Input value={form.slug} onChange={(e) => setForm({ ...form, slug: slugify(e.target.value) })} required /></div>
            <div className="space-y-2">
              <Label>Type</Label>
              <Select value={form.type_id || undefined} onValueChange={(v) => setForm({ ...form, type_id: v })}>
                <SelectTrigger><SelectValue placeholder="Select type" /></SelectTrigger>
                <SelectContent>{types.map((t) => <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>)}</SelectContent>
              </Select>
            </div>
            <div className="space-y-2"><Label>Admin / coordinator email</Label><Input type="email" value={form.admin_email} onChange={(e) => setForm({ ...form, admin_email: e.target.value })} /></div>
            <div className="space-y-2 md:col-span-2"><Label>Venue</Label><Input value={form.venue} onChange={(e) => setForm({ ...form, venue: e.target.value })} /></div>
            <div className="space-y-2 md:col-span-2"><Label>Description</Label><Textarea value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} rows={3} /></div>
            <div className="space-y-2"><Label>Starts</Label><Input type="datetime-local" value={form.starts_at} onChange={(e) => setForm({ ...form, starts_at: e.target.value })} /></div>
            <div className="space-y-2"><Label>Ends</Label><Input type="datetime-local" value={form.ends_at} onChange={(e) => setForm({ ...form, ends_at: e.target.value })} /></div>
            <div className="space-y-2"><Label>Registration opens</Label><Input type="datetime-local" value={form.registration_opens_at} onChange={(e) => setForm({ ...form, registration_opens_at: e.target.value })} /></div>
            <div className="space-y-2"><Label>Registration closes</Label><Input type="datetime-local" value={form.registration_closes_at} onChange={(e) => setForm({ ...form, registration_closes_at: e.target.value })} /></div>
          </div>

          <div className="rounded-xl border p-4 space-y-3">
            <p className="text-sm font-semibold">Custom form fields</p>
            <ul className="text-xs text-gray-500 space-y-1">
              {form.form_fields.map((f) => (
                <li key={f.name} className="flex justify-between">
                  <span>{f.label} ({f.type}){f.required ? " *" : ""}</span>
                  {!["full_name", "email", "phone"].includes(f.name) && (
                    <button type="button" className="text-red-600" onClick={() => setForm({ ...form, form_fields: form.form_fields.filter((x) => x.name !== f.name) })}>Remove</button>
                  )}
                </li>
              ))}
            </ul>
            <div className="grid sm:grid-cols-4 gap-2">
              <Input placeholder="field_name" value={fieldDraft.name} onChange={(e) => setFieldDraft({ ...fieldDraft, name: e.target.value })} />
              <Input placeholder="Label" value={fieldDraft.label} onChange={(e) => setFieldDraft({ ...fieldDraft, label: e.target.value })} />
              <Select value={fieldDraft.type} onValueChange={(v) => setFieldDraft({ ...fieldDraft, type: v })}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  {["text", "email", "tel", "number", "textarea", "select"].map((t) => <SelectItem key={t} value={t}>{t}</SelectItem>)}
                </SelectContent>
              </Select>
              <Button type="button" variant="outline" onClick={addField}>Add field</Button>
            </div>
          </div>

          <div className="flex gap-4">
            <label className="flex items-center gap-2 text-sm"><Checkbox checked={form.is_active} onCheckedChange={(v) => setForm({ ...form, is_active: Boolean(v) })} /> Active</label>
            <label className="flex items-center gap-2 text-sm"><Checkbox checked={form.allow_public_registration} onCheckedChange={(v) => setForm({ ...form, allow_public_registration: Boolean(v) })} /> Public registration</label>
          </div>

          <div className="flex gap-2">
            <Button type="submit" className="bg-red-600 hover:bg-red-700">{editing ? "Save changes" : "Create program"}</Button>
            <Button type="button" variant="outline" onClick={reset}>Cancel</Button>
          </div>
        </form>
      )}

      <div className="mt-8 grid gap-4">
        {programs.map((p) => (
          <div key={p.id} className="rounded-2xl border bg-white p-5 flex flex-wrap items-start justify-between gap-4">
            <div>
              <h3 className="font-semibold text-lg">{p.title}</h3>
              <p className="text-sm text-gray-500 mt-1">{p.type_name} · {p.registration_count || 0} registrations</p>
              <Link to={`/register/${p.slug}`} target="_blank" className="inline-flex items-center gap-1 text-sm text-red-600 mt-2 hover:underline">
                /register/{p.slug} <ExternalLink size={12} />
              </Link>
            </div>
            <div className="flex gap-2">
              <Button asChild variant="outline" size="sm"><Link to={`/admin/programs/registrations?program=${p.id}`}>Registrations</Link></Button>
              {canEdit && <Button size="sm" variant="outline" onClick={() => editProgram(p)}>Edit</Button>}
              {canDelete && <Button size="sm" variant="outline" className="text-red-600" onClick={async () => { await authApi.deleteProgram(p.id); load(); }}><Trash2 size={14} /></Button>}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
