import { useEffect, useState } from "react";
import { toast } from "sonner";
import { formatApiError, listPublicChurchRoles, submitChurchMembership, markChurchMemberEmailed } from "../lib/api";
import { sendChurchMembershipEmails } from "../lib/email";
import { useSettings } from "../context/SettingsContext";
import { Card, CardContent } from "../components/ui/card";
import { Badge } from "../components/ui/badge";
import { Button } from "../components/ui/button";
import { Input } from "../components/ui/input";
import { Label } from "../components/ui/label";
import { Textarea } from "../components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "../components/ui/select";
import { BranchSelect } from "../components/programs/BranchSelect";
import { Church, Send } from "lucide-react";

export function ChurchMembershipPage() {
  const { settings } = useSettings();
  const [roles, setRoles] = useState([]);
  const [submitting, setSubmitting] = useState(false);
  const [done, setDone] = useState(false);
  const [form, setForm] = useState({
    full_name: "", email: "", phone: "", gender: "", date_of_birth: "",
    address: "", city: "", state: "", country: "Nigeria",
    role_id: "", branch_id: "", ministry: "", baptism_status: "", marital_status: "",
    occupation: "", emergency_contact_name: "", emergency_contact_phone: "", notes: "",
  });

  useEffect(() => {
    listPublicChurchRoles().then(setRoles).catch(() => setRoles([]));
  }, []);

  const change = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const submit = async (e) => {
    e.preventDefault();
    setSubmitting(true);
    try {
      const result = await submitChurchMembership({
        full_name: form.full_name,
        email: form.email,
        phone: form.phone,
        gender: form.gender,
        date_of_birth: form.date_of_birth || null,
        address: form.address,
        city: form.city,
        state: form.state,
        country: form.country,
        role_id: form.role_id,
        branch_id: form.branch_id,
        ministry: form.ministry,
        baptism_status: form.baptism_status,
        marital_status: form.marital_status,
        occupation: form.occupation,
        emergency_contact_name: form.emergency_contact_name,
        emergency_contact_phone: form.emergency_contact_phone,
        notes: form.notes,
      });
      try {
        await sendChurchMembershipEmails({
          fullName: form.full_name,
          email: form.email,
          phone: form.phone,
          roleName: result.roleName,
          branchName: result.branchName,
          adminEmail: settings.notificationEmail,
        });
        await markChurchMemberEmailed(result.id);
      } catch (emailErr) {
        console.warn(emailErr);
      }
      setDone(true);
      toast.success("Registration received! Check your email for confirmation.");
    } catch (err) {
      toast.error(formatApiError(err.message));
    } finally {
      setSubmitting(false);
    }
  };

  if (done) {
    return (
      <div className="min-h-[60vh] flex items-center justify-center px-4">
        <Card className="max-w-md w-full text-center p-8">
          <Church className="h-12 w-12 text-red-600 mx-auto mb-4" />
          <h1 className="text-2xl font-bold">Welcome to the family!</h1>
          <p className="text-gray-600 mt-3">Your membership registration has been received. Our leadership team will review your application.</p>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-red-50 via-white to-orange-50 py-16">
      <div className="max-w-3xl mx-auto px-4">
        <div className="text-center mb-8">
          <Badge className="bg-red-100 text-red-700 mb-3">Membership</Badge>
          <h1 className="text-3xl md:text-4xl font-bold text-gray-900">Join Fire-Fire International</h1>
          <p className="text-gray-600 mt-4 max-w-xl mx-auto">
            Register as a bonafide member of the church. Pastors, workers, and members can complete this form with full details.
          </p>
        </div>

        <Card className="shadow-lg border-0">
          <CardContent className="p-8">
            <form onSubmit={submit} className="space-y-5">
              <div className="grid md:grid-cols-2 gap-4">
                <div className="space-y-2 md:col-span-2">
                  <Label>Full Name *</Label>
                  <Input name="full_name" value={form.full_name} onChange={change} required className="focus:border-red-500" />
                </div>
                <div className="space-y-2">
                  <Label>Email *</Label>
                  <Input name="email" type="email" value={form.email} onChange={change} required className="focus:border-red-500" />
                </div>
                <div className="space-y-2">
                  <Label>Phone *</Label>
                  <Input name="phone" type="tel" value={form.phone} onChange={change} required minLength={7} className="focus:border-red-500" />
                </div>
                <div className="space-y-2">
                  <Label>Gender</Label>
                  <Select value={form.gender || undefined} onValueChange={(v) => setForm({ ...form, gender: v })}>
                    <SelectTrigger><SelectValue placeholder="Select" /></SelectTrigger>
                    <SelectContent>
                      {["Male", "Female"].map((g) => <SelectItem key={g} value={g}>{g}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label>Date of birth</Label>
                  <Input name="date_of_birth" type="date" value={form.date_of_birth} onChange={change} className="focus:border-red-500" />
                </div>
                <div className="space-y-2 md:col-span-2">
                  <Label>Church role *</Label>
                  <Select value={form.role_id || undefined} onValueChange={(v) => setForm({ ...form, role_id: v })} required>
                    <SelectTrigger><SelectValue placeholder="Select your role" /></SelectTrigger>
                    <SelectContent>
                      {roles.map((r) => <SelectItem key={r.id} value={r.id}>{r.name}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2 md:col-span-2">
                  <BranchSelect value={form.branch_id} onChange={(v) => setForm({ ...form, branch_id: v })} />
                </div>
                <div className="space-y-2 md:col-span-2">
                  <Label>Address</Label>
                  <Input name="address" value={form.address} onChange={change} className="focus:border-red-500" />
                </div>
                <div className="space-y-2">
                  <Label>City</Label>
                  <Input name="city" value={form.city} onChange={change} className="focus:border-red-500" />
                </div>
                <div className="space-y-2">
                  <Label>State</Label>
                  <Input name="state" value={form.state} onChange={change} className="focus:border-red-500" />
                </div>
                <div className="space-y-2">
                  <Label>Ministry / department</Label>
                  <Input name="ministry" value={form.ministry} onChange={change} className="focus:border-red-500" />
                </div>
                <div className="space-y-2">
                  <Label>Occupation</Label>
                  <Input name="occupation" value={form.occupation} onChange={change} className="focus:border-red-500" />
                </div>
                <div className="space-y-2">
                  <Label>Baptism status</Label>
                  <Input name="baptism_status" value={form.baptism_status} onChange={change} placeholder="e.g. Baptized" className="focus:border-red-500" />
                </div>
                <div className="space-y-2">
                  <Label>Marital status</Label>
                  <Input name="marital_status" value={form.marital_status} onChange={change} className="focus:border-red-500" />
                </div>
                <div className="space-y-2">
                  <Label>Emergency contact name</Label>
                  <Input name="emergency_contact_name" value={form.emergency_contact_name} onChange={change} className="focus:border-red-500" />
                </div>
                <div className="space-y-2">
                  <Label>Emergency contact phone</Label>
                  <Input name="emergency_contact_phone" value={form.emergency_contact_phone} onChange={change} className="focus:border-red-500" />
                </div>
                <div className="space-y-2 md:col-span-2">
                  <Label>Additional notes</Label>
                  <Textarea name="notes" value={form.notes} onChange={change} rows={3} className="focus:border-red-500" />
                </div>
              </div>
              <Button type="submit" disabled={submitting} className="w-full bg-red-600 hover:bg-red-700">
                {submitting ? "Submitting…" : (<><Send className="h-4 w-4 mr-2" />Submit membership registration</>)}
              </Button>
            </form>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}
