import { useState } from "react";
import { Link } from "react-router-dom";
import { useActiveAnnouncements } from "../hooks/useActiveAnnouncements";
import { Button } from "./ui/button";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "./ui/dialog";

const dismissKey = (id) => `ffiemc_announcement_dismissed_${id}`;

function isDismissed(item) {
  if (!item?.show_once) return false;
  try {
    const raw = localStorage.getItem(dismissKey(item.id));
    if (!raw) return false;
    const parsed = JSON.parse(raw);
    if (item.updated_at && parsed.at && new Date(item.updated_at) > new Date(parsed.at)) {
      return false;
    }
    return true;
  } catch {
    return false;
  }
}

function dismiss(item) {
  try {
    localStorage.setItem(
      dismissKey(item.id),
      JSON.stringify({ at: new Date().toISOString() })
    );
  } catch {
    /* ignore */
  }
}

export function AnnouncementPopup() {
  const list = useActiveAnnouncements("popup");
  const item = list.find((row) => row && !isDismissed(row)) || null;
  const [closedId, setClosedId] = useState(null);
  const open = Boolean(item) && closedId !== item.id;

  const close = () => {
    if (item) {
      dismiss(item);
      setClosedId(item.id);
    }
  };

  if (!item) return null;

  const link = (item.link_url || "").trim();
  const isInternal = link.startsWith("/");
  const showRoute = item.route_enabled !== false && Boolean(link);
  const isEventFlyer = Boolean(item.image);

  return (
    <Dialog
      open={open}
      onOpenChange={(next) => {
        if (!next) close();
      }}
    >
      <DialogContent
        className={`p-0 overflow-hidden gap-0 sm:rounded-2xl [&>button]:right-3 [&>button]:top-3 [&>button]:z-10 ${
          isEventFlyer ? "max-w-2xl" : "max-w-lg"
        }`}
      >
        {item.image ? (
          <div className={`relative w-full bg-gray-100 ${isEventFlyer ? "aspect-[3/4] max-h-[70vh]" : "aspect-[16/9]"}`}>
            <img
              src={item.image}
              alt=""
              className="absolute inset-0 h-full w-full object-cover"
            />
          </div>
        ) : null}

        <div className="p-6 space-y-4">
          <DialogHeader>
            <DialogTitle className="text-2xl font-bold text-gray-900 pr-8">
              {item.title}
            </DialogTitle>
          </DialogHeader>
          {item.body ? (
            <p className="text-gray-600 whitespace-pre-wrap leading-relaxed">{item.body}</p>
          ) : null}

          <div className="flex flex-wrap gap-2 pt-1">
            {showRoute ? (
              isInternal ? (
                <Button asChild className="bg-red-600 hover:bg-red-700">
                  <Link to={link} onClick={close}>
                    {item.link_text || "Learn more"}
                  </Link>
                </Button>
              ) : (
                <Button asChild className="bg-red-600 hover:bg-red-700">
                  <a href={link} target="_blank" rel="noreferrer" onClick={close}>
                    {item.link_text || "Learn more"}
                  </a>
                </Button>
              )
            ) : null}
            <Button variant="outline" onClick={close}>
              Close
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

export default AnnouncementPopup;
