import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { toast } from "sonner";
import { formatApiError, getPublicProgram, submitProgramRegistration, markProgramRegistrationEmailed } from "../lib/api";
import { sendProgramRegistrationEmails } from "../lib/email";
import { useSettings } from "../context/SettingsContext";
import { BranchSelect } from "../components/programs/BranchSelect";
import { DynamicFormFields, buildFormData } from "../components/programs/DynamicFormFields";
import { Card, CardContent } from "../components/ui/card";
import { Badge } from "../components/ui/badge";
import { Button } from "../components/ui/button";
import { Input } from "../components/ui/input";
import { Label } from "../components/ui/label";
import { Calendar, MapPin, Send } from "lucide-react";

export function ProgramRegisterPage() {
  const { slug } = useParams();
  const { settings } = useSettings();
  const [program, setProgram] = useState(null);
  const [error, setError] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [done, setDone] = useState(false);
  const [form, setForm] = useState({ full_name: "", email: "", phone: "", branch_id: "", extras: {} });

  useEffect(() => {
    getPublicProgram(slug)
      .then(setProgram)
      .catch((e) => setError(e.message || "Program not found"));
  }, [slug]);

  const submit = async (e) => {
    e.preventDefault();
    setSubmitting(true);
    try {
      const form_data = buildFormData(program.formFields, form.extras);
      const result = await submitProgramRegistration(slug, {
        full_name: form.full_name,
        email: form.email,
        phone: form.phone,
        branch_id: form.branch_id,
        form_data,
      });
      try {
        await sendProgramRegistrationEmails({
          programTitle: result.programTitle || program.title,
          adminEmail: result.adminEmail,
          fullName: form.full_name,
          email: form.email,
          phone: form.phone,
          formData: form_data,
          branchName: result.branchName,
          fallbackAdminEmail: settings.notificationEmail,
        });
        await markProgramRegistrationEmailed(result.id);
      } catch (emailErr) {
        console.warn(emailErr);
      }
      setDone(true);
      toast.success("Registration successful! Check your email for confirmation.");
    } catch (err) {
      toast.error(formatApiError(err.message));
    } finally {
      setSubmitting(false);
    }
  };

  if (error) {
    return (
      <div className="min-h-[60vh] flex items-center justify-center px-4">
        <p className="text-red-600 text-center">{error}</p>
      </div>
    );
  }

  if (!program) {
    return <div className="min-h-[60vh] flex items-center justify-center text-gray-500">Loading…</div>;
  }

  if (done) {
    return (
      <div className="min-h-[60vh] flex items-center justify-center px-4">
        <Card className="max-w-md w-full text-center p-8">
          <h1 className="text-2xl font-bold text-gray-900">You're registered!</h1>
          <p className="text-gray-600 mt-3">Thank you for registering for {program.title}. A confirmation has been sent to your email.</p>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-red-50 via-white to-orange-50 py-16">
      <div className="max-w-2xl mx-auto px-4">
        <div className="text-center mb-8">
          {program.typeName && <Badge className="bg-red-100 text-red-700 mb-3">{program.typeName}</Badge>}
          <h1 className="text-3xl md:text-4xl font-bold text-gray-900">{program.title}</h1>
          <p className="text-gray-600 mt-4">{program.description}</p>
          <div className="flex flex-wrap justify-center gap-4 mt-4 text-sm text-gray-500">
            {program.venue && <span className="inline-flex items-center gap-1"><MapPin size={14} /> {program.venue}</span>}
            {program.startsAt && <span className="inline-flex items-center gap-1"><Calendar size={14} /> {new Date(program.startsAt).toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" })}</span>}
          </div>
        </div>

        <Card className="shadow-lg border-0">
          <CardContent className="p-8">
            <form onSubmit={submit} className="space-y-5">
              <div className="grid md:grid-cols-2 gap-4">
                <div className="space-y-2 md:col-span-2">
                  <Label>Full Name *</Label>
                  <Input value={form.full_name} onChange={(e) => setForm({ ...form, full_name: e.target.value })} required className="focus:border-red-500" />
                </div>
                <div className="space-y-2">
                  <Label>Email *</Label>
                  <Input type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} required className="focus:border-red-500" />
                </div>
                <div className="space-y-2">
                  <Label>Phone *</Label>
                  <Input type="tel" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} required className="focus:border-red-500" />
                </div>
              </div>
              <BranchSelect value={form.branch_id} onChange={(v) => setForm({ ...form, branch_id: v })} />
              <DynamicFormFields
                fields={program.formFields}
                values={form.extras}
                onChange={(name, val) => setForm({ ...form, extras: { ...form.extras, [name]: val } })}
              />
              <Button type="submit" disabled={submitting} className="w-full bg-red-600 hover:bg-red-700">
                {submitting ? "Submitting…" : (<><Send className="h-4 w-4 mr-2" />Complete registration</>)}
              </Button>
            </form>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}
